# BPE (byte-pair merging): learn merges from a tiny corpus, then tokenize new text.
from collections import Counter

corpus = "low lower lowest new newer newest wide wider widest".split()
words = [list(w) + ["_"] for w in corpus]          # "_" marks end of word


def most_common_pair(words):
    pairs = Counter()
    for w in words:
        for a, b in zip(w, w[1:]):
            pairs[(a, b)] += 1
    return pairs.most_common(1)[0]


def merge(words, pair):
    out = []
    for w in words:
        i, new = 0, []
        while i < len(w):
            if i + 1 < len(w) and (w[i], w[i + 1]) == pair:
                new.append(w[i] + w[i + 1]); i += 2
            else:
                new.append(w[i]); i += 1
        out.append(new)
    return out


merges = []
for step in range(8):
    pair, count = most_common_pair(words)
    words = merge(words, pair)
    merges.append(pair)
    print(f"merge {step + 1}: {pair[0]!r}+{pair[1]!r} (seen {count}x)")


def tokenize(text):
    w = list(text) + ["_"]
    for pair in merges:                               # apply merges in learned order
        w = merge([w], pair)[0]
    return w


for text in ["newest", "lowering", "zzz"]:
    toks = tokenize(text)
    print(f"{text!r:11} -> {toks}  ({len(toks)} tokens)")

# Temperature and top-p on one fixed set of next-token scores (logits).
import math

logits = {"refund": 4.0, "replace": 3.2, "return": 2.9, "apologise": 1.0, "banana": -2.0}


def softmax(scores, temperature):
    scaled = {t: s / temperature for t, s in scores.items()}
    top = max(scaled.values())
    exp = {t: math.exp(s - top) for t, s in scaled.items()}
    total = sum(exp.values())
    return {t: e / total for t, e in exp.items()}


def top_p(probs, p):
    kept, mass = {}, 0.0
    for tok, pr in sorted(probs.items(), key=lambda kv: -kv[1]):
        kept[tok] = pr
        mass += pr
        if mass >= p:
            break
    return {t: pr / mass for t, pr in kept.items()}     # renormalise survivors


for temp in (0.2, 1.0, 2.0):
    probs = softmax(logits, temp)
    row = "  ".join(f"{t}={pr:.2f}" for t, pr in probs.items())
    print(f"T={temp}: {row}")

print()
base = softmax(logits, 1.0)
for p in (0.5, 0.9, 1.0):
    kept = top_p(base, p)
    print(f"top_p={p}: keeps {len(kept)} tokens ->", "  ".join(f"{t}={pr:.2f}" for t, pr in kept.items()))

# Prompt caching is a prefix match. Count how much of request 2 is identical to request 1 from the start.
def words(parts):
    return " ".join(parts).split()                    # words stand in for tokens here


def shared_prefix(a, b):
    n = 0
    for x, y in zip(a, b):
        if x != y:
            break
        n += 1
    return n


