# Three checks before code trusts a model reply: stop reason, shape, values. Replies are scripted samples.
import json

SCHEMA = {                                             # field: (type, nullable)
    "store_name": (str, False), "total": (float, False),
    "gst_number": (str, True),                         # nullable: many bills have none
    "items": (list, False),
}


def check(reply):
    if reply["stop_reason"] == "max_tokens":
        return "REJECT truncated: raise the output cap or ask for less"
    try:
        data = json.loads(reply["text"])
    except json.JSONDecodeError:
        return "REJECT not JSON"
    for field, (kind, nullable) in SCHEMA.items():
        if field not in data:
            return f"REJECT missing {field}"
        value = data[field]
        if value is None and nullable:
            continue
        if not isinstance(value, kind):
            return f"REJECT {field} should be {kind.__name__}"
    line_sum = round(sum(i["price"] * i["qty"] for i in data["items"]), 2)
    if abs(line_sum - data["total"]) > 0.01:
        return f"FLAG   total {data['total']} but items add up to {line_sum}: ask the user to confirm"
    gst = data["gst_number"]
    if gst is not None and len(gst) != 15:
        return f"REJECT gst_number {gst!r} is not 15 characters: likely invented"
    return "OK"


ITEMS = '[{"name": "milk", "price": 68.0, "qty": 2}, {"name": "bread", "price": 45.0, "qty": 1}]'
samples = {
    "good bill, no GST on it": {"stop_reason": "end", "text": f'{{"store_name": "FreshMart", "total": 181.0, "gst_number": null, "items": {ITEMS}}}'},
    "cut off by the output cap": {"stop_reason": "max_tokens", "text": '{"store_name": "FreshMart", "total": 181.0, "gst_nu'},
    "model misread the total": {"stop_reason": "end", "text": f'{{"store_name": "FreshMart", "total": 187.0, "gst_number": null, "items": {ITEMS}}}'},
    "invented a GST number": {"stop_reason": "end", "text": f'{{"store_name": "FreshMart", "total": 181.0, "gst_number": "GST12345", "items": {ITEMS}}}'},
    "total returned as text": {"stop_reason": "end", "text": f'{{"store_name": "FreshMart", "total": "181", "gst_number": null, "items": {ITEMS}}}'},
}
for name, reply in samples.items():
    print(f"{name:28} {check(reply)}")

