# The backend's streaming relay: provider events in, your own SSE events out. The provider is simulated.
import json

WORDS = "Your order A17 is out for delivery and should arrive by 18:40 today .".split()


def provider_stream(fail_at=None, log=None):
    """Stands in for the model provider. Closing it early is how a real upstream call gets cancelled."""
    sent = 0
    try:
        for i, w in enumerate(WORDS):
            if i == fail_at:
                raise ConnectionError("provider overloaded")
            sent += 1
            yield {"type": "delta", "text": w + " "}
        yield {"type": "stop", "usage": {"output_tokens": sent}}
    finally:
        log["generated"] = sent                       # what you are billed for


def relay(upstream, request_id):
    """Maps provider events to the app's own event names, so the app never depends on one provider's format."""
    start = json.dumps({"request_id": request_id})
    yield f"event: start\ndata: {start}\n\n"
    try:
        for ev in upstream:
            if ev["type"] == "delta":
                yield f"event: text\ndata: {json.dumps({'t': ev['text']})}\n\n"
            else:
                yield f"event: done\ndata: {json.dumps(ev['usage'])}\n\n"
    except ConnectionError as err:
        yield f"event: error\ndata: {json.dumps({'retryable': True, 'message': str(err)})}\n\n"
    finally:
        upstream.close()                              # client went away or we finished: stop the upstream call


def client(stream, leave_after=None):
    """Stands in for the phone: parses SSE frames, appends text, may leave the screen mid-answer."""
    text, last = "", None
    for n, frame in enumerate(stream, start=1):
        event, data = [line.split(": ", 1)[1] for line in frame.strip().split("\n")]
        last = event
        if event == "text":
            text += json.loads(data)["t"]
        if leave_after and n >= leave_after:
            stream.close()                            # user left the screen
            return text, "client left"
    return text, last


for label, fail_at, leave_after in [("normal", None, None), ("user leaves the screen early", None, 5), ("provider fails mid-stream", 6, None)]:
    log = {}
    text, ended = client(relay(provider_stream(fail_at, log), "req_81"), leave_after)
    print(f"{label:30} ended: {ended:11} tokens generated {log['generated']:>2}/{len(WORDS)}  shown: {text.strip()!r}")

# A rate limit counted in tokens, not requests. Reserve an estimate, then settle with the real usage.
class TokenBucket:
    def __init__(self, capacity, refill_per_min):
        self.capacity, self.rate, self.level, self.t = capacity, refill_per_min / 60, capacity, 0.0

    def _refill(self, now):
        self.level = min(self.capacity, self.level + (now - self.t) * self.rate)
        self.t = now

    def reserve(self, now, estimate):
        self._refill(now)
        if estimate > self.level:
            return False, round((estimate - self.level) / self.rate)       # seconds until it would fit
        self.level -= estimate
        return True, 0

    def settle(self, estimate, actual):
        self.level = min(self.capacity, self.level + estimate - actual)    # give back what was not used


bucket = TokenBucket(capacity=20_000, refill_per_min=10_000)
print("one user, 20,000-token bucket refilling 10,000 per minute")
for now, estimate, actual in [(0, 6000, 5200), (15, 6000, 6100), (30, 6000, 5900), (45, 6000, 6000), (60, 6000, 5800), (75, 6000, 0), (75, 1200, 1100)]:
    ok, wait = bucket.reserve(now, estimate)
    if ok:
        bucket.settle(estimate, actual)
        print(f"  t={now:>2}s  request ~{estimate:>5} tokens  ALLOWED  used {actual:>5}  left {bucket.level:>7,.0f}")
    else:
        print(f"  t={now:>2}s  request ~{estimate:>5} tokens  429      Retry-After: {wait}s   left {bucket.level:>7,.0f}")

print("\nthe same traffic under a requests-per-minute limit of 10: all 7 allowed,")
print("whether each request is 1,200 tokens or 120,000. Tokens are what cost money.")

