# BM25 + cosine similarity + reciprocal rank fusion, standard library only.
import math
from collections import Counter

docs = {
    "d1": "refund is issued to the original payment method within 5 days",
    "d2": "error E-4012 means the payment gateway timed out at checkout",
    "d3": "you can get your money back for damaged or expired items",
    "d4": "delivery slots can be changed up to one hour before dispatch",
}
tok = lambda s: s.lower().replace("-", "").split()
N = len(docs)
df = Counter(t for d in docs.values() for t in set(tok(d)))
avg_len = sum(len(tok(d)) for d in docs.values()) / N


def bm25(query, doc, k1=1.5, b=0.75):
    tf, length, score = Counter(tok(doc)), len(tok(doc)), 0.0
    for t in tok(query):
        if t not in tf:
            continue
        idf = math.log((N - df[t] + 0.5) / (df[t] + 0.5) + 1)
        score += idf * tf[t] * (k1 + 1) / (tf[t] + k1 * (1 - b + b * length / avg_len))
    return score


# Stand-in "embeddings": 3 hand-set meaning axes [money-back, payment-error, delivery].
# A real system gets these vectors from an embedding model.
vec = {"d1": [0.9, 0.2, 0.0], "d2": [0.1, 0.9, 0.0], "d3": [0.95, 0.0, 0.05], "d4": [0.0, 0.0, 1.0]}
# The second query vector is deliberately vague: embeddings blur exact codes like E-4012.
qvec = {"refund on spoiled food": [0.9, 0.0, 0.1], "error E-4012 at checkout": [0.5, 0.5, 0.1]}


def cosine(a, b):
    dot = sum(x * y for x, y in zip(a, b))
    return dot / (math.sqrt(sum(x * x for x in a)) * math.sqrt(sum(y * y for y in b)))


def rrf(*rankings, k=60):
    score = Counter()
    for ranking in rankings:
        for rank, doc_id in enumerate(ranking, start=1):
            score[doc_id] += 1 / (k + rank)
    return [d for d, _ in score.most_common()]


for q in qvec:
    kw = [d for d in sorted(docs, key=lambda d: -bm25(q, docs[d])) if bm25(q, docs[d]) > 0]
    sem = sorted(docs, key=lambda d: -cosine(qvec[q], vec[d]))
    print(f"query: {q}")
    print("  keyword :", kw)
    print("  vector  :", sem)
    print("  hybrid  :", rrf(kw, sem))

