# A run that crashes mid-task, with and without checkpoints. Count what gets executed twice.
import json

PLAN = [("get_order", {"order_id": "A17"}), ("check_policy", {"item": "milk"}),
        ("issue_refund", {"order_id": "A17", "amount": 68}), ("send_confirmation", {"order_id": "A17"})]
executed, refunds, store = [], [], {}                   # store stands in for a database table of checkpoints


def run_tool(name, args, step_key):
    executed.append(name)
    if name == "issue_refund":
        if step_key in {r["key"] for r in refunds}:      # idempotency key = task + step
            return "already refunded (replayed)"
        refunds.append({"key": step_key, **args})
    return f"{name} ok"


def run(task_id, crash_at=None, checkpoints=True):
    state = json.loads(store[task_id]) if (checkpoints and task_id in store) else {"next": 0, "results": []}
    for i in range(state["next"], len(PLAN)):
        if i == crash_at:
            raise RuntimeError(f"process killed before step {i + 1}")
        name, args = PLAN[i]
        state["results"].append(run_tool(name, args, f"{task_id}-step{i}"))
        state["next"] = i + 1
        if checkpoints:
            store[task_id] = json.dumps(state)           # saved after every step
    return state["results"]


for label, checkpoints in [("no checkpoints", False), ("checkpoint after every step", True)]:
    executed.clear(); refunds.clear(); store.clear()
    try:
        run("task42", crash_at=3, checkpoints=checkpoints)      # dies after the refund, before the confirmation
    except RuntimeError as err:
        first = len(executed)
    run("task42", checkpoints=checkpoints)                       # the restart
    print(f"{label:28} tool executions: {first} before the crash + {len(executed) - first} after = {len(executed)}"
          f"   refunds recorded: {len(refunds)}   order: {' > '.join(executed[first:])}")
print("\nWithout checkpoints the restart repeats every step. Only the idempotency key stops a second refund.")

# An agent loop you own, with four stop conditions. The "model" is a script so this runs offline.
import json

ORDERS = {"A17": {"status": "delivered", "total": 480}}


def get_order(order_id):
    return ORDERS.get(order_id) or {"error": f"order {order_id} not found"}


TOOLS = {"get_order": get_order}


def scripted_model(script):
    steps = iter(script)
    return lambda messages: next(steps)


def run_agent(model, question, max_steps=5, token_budget=400):
    messages, spent, last_call, repeats = [{"role": "user", "content": question}], 0, None, 0
    for step in range(1, max_steps + 1):
        reply = model(messages)
        spent += reply["tokens"]
        if spent > token_budget:
            return f"STOP budget: spent {spent} > {token_budget} tokens after {step} steps"
        if "answer" in reply:
            return f"DONE in {step} steps, {spent} tokens: {reply['answer']}"
        call = (reply["tool"], json.dumps(reply["args"], sort_keys=True))
        repeats = repeats + 1 if call == last_call else 0
        if repeats >= 2:
            return f"STOP loop: {reply['tool']}{reply['args']} repeated 3 times"
        last_call = call
        result = TOOLS[reply["tool"]](**reply["args"])
        messages += [{"role": "assistant", "content": reply}, {"role": "tool", "content": result}]
    return f"STOP steps: reached max_steps={max_steps} without an answer"


good = [{"tool": "get_order", "args": {"order_id": "A17"}, "tokens": 90},
        {"answer": "Order A17 was delivered. Total 480.", "tokens": 60}]
stuck = [{"tool": "get_order", "args": {"order_id": "Z99"}, "tokens": 90}] * 6
wander = [{"tool": "get_order", "args": {"order_id": f"B{i}"}, "tokens": 50} for i in range(9)]
greedy = [{"tool": "get_order", "args": {"order_id": f"C{i}"}, "tokens": 180} for i in range(9)]

for name, script in [("happy path", good), ("same call forever", stuck), ("never finishes", wander), ("expensive steps", greedy)]:
    print(f"{name:18} -> {run_agent(scripted_model(script), 'Where is my order?')}")

