# Routing with quality in the picture. Assumptions are stated up front; change them and rerun.
import random

random.seed(8)
COST = {"small": 0.0004, "large": 0.0060}
ACC = {("small", "easy"): 0.96, ("small", "hard"): 0.62, ("large", "easy"): 0.98, ("large", "hard"): 0.93}
EASY_SHARE = 0.65              # share of traffic that is easy
ROUTER_ACC = 0.88              # how often a cheap classifier labels difficulty correctly
VALIDATOR_CATCH = 0.70         # share of the small model's wrong answers that an output check detects

requests = ["easy" if random.random() < EASY_SHARE else "hard" for _ in range(20000)]
correct = lambda model, kind: random.random() < ACC[(model, kind)]


def run(strategy):
    cost = right = 0
    for kind in requests:
        if strategy == "all large":
            cost += COST["large"]; right += correct("large", kind)
        elif strategy == "all small":
            cost += COST["small"]; right += correct("small", kind)
        elif strategy == "router":
            guess = kind if random.random() < ROUTER_ACC else ("hard" if kind == "easy" else "easy")
            model = "small" if guess == "easy" else "large"
            cost += COST[model]; right += correct(model, kind)
        elif strategy == "cascade":                          # try small; escalate when the check fails
            cost += COST["small"]
            ok = correct("small", kind)
            if ok:
                right += 1
            elif random.random() < VALIDATOR_CATCH:
                cost += COST["large"]; right += correct("large", kind)
        elif strategy == "router + cascade":
            guess = kind if random.random() < ROUTER_ACC else ("hard" if kind == "easy" else "easy")
            if guess == "hard":
                cost += COST["large"]; right += correct("large", kind)
            else:
                cost += COST["small"]
                ok = correct("small", kind)
                if ok:
                    right += 1
                elif random.random() < VALIDATOR_CATCH:
                    cost += COST["large"]; right += correct("large", kind)
    return cost / len(requests), right / len(requests)


base_cost, base_acc = run("all large")
print(f"{'strategy':18} cost/request  vs all-large  accuracy  change")
for s in ("all large", "all small", "router", "cascade", "router + cascade"):
    c, a = (base_cost, base_acc) if s == "all large" else run(s)
    print(f"{s:18} ${c:.5f}     {c / base_cost:>6.0%}      {a:>6.1%}   {'+' if a >= base_acc else '-'}{abs(a - base_acc):.1%}")
print("\nThe cheapest options lose accuracy. Under these assumptions, a router with a cascade behind it matches all-large at under half the cost.")
print("The assumptions are the whole result: measure your own accuracy per route before believing any of these rows.")

# Router + semantic cache + fallback chain. Model calls are simulated; prices are placeholders.
import math

COST = {"small": 0.0004, "large": 0.0060, "cache": 0.0}
cache = []                                               # (scope, vector, answer)


def embed(text):                                         # stand-in embedding: counts of 4 keywords
    words = text.lower().replace("?", "").split()
    return [sum(w.startswith(k) for w in words) for k in ("deliver", "refund", "why", "compare")]


def cosine(a, b):
    na, nb = math.sqrt(sum(x * x for x in a)), math.sqrt(sum(x * x for x in b))
    return 0.0 if not na or not nb else sum(x * y for x, y in zip(a, b)) / (na * nb)


def route(question):
    hard = len(question.split()) > 12 or any(w in question.lower() for w in ("why", "compare", "explain"))
    return "large" if hard else "small"


def call(model, question, down=()):
    if model in down:
        raise TimeoutError(model)
    return f"[{model}] answer"


def answer(question, scope, personal=False, down=()):
    v = embed(question)
    if not personal:
        for s, cv, text in cache:
            if s == scope and cosine(v, cv) > 0.95:
                return "cache", COST["cache"]
    first = route(question)
    for model in [first] + [m for m in ("large", "small") if m != first]:
        try:
            text = call(model, question, down)
            if not personal:
                cache.append((scope, v, text))
            return model, COST[model]
        except TimeoutError:
            continue
    return "degraded reply", 0.0


total = 0.0
for q, scope, personal, down in [
    ("What are your delivery hours?", "tenantA", False, ()),
    ("What are the delivery hours", "tenantA", False, ()),          # same meaning, same tenant -> cache
    ("What are your delivery hours?", "tenantB", False, ()),        # other tenant -> no cache
    ("Where is my refund?", "tenantA", True, ()),                   # personal -> never cached
    ("Why was I charged twice and can you compare both invoices?", "tenantA", True, ()),
    ("Why is my order late?", "tenantA", True, ("large",)),         # large is down -> fallback
]:
    used, cost = answer(q, scope, personal, down)
    total += cost
    print(f"{used:8} ${cost:.4f}  {scope}  {q}")
print(f"total ${total:.4f}   (all on large would be ${6 * COST['large']:.4f})")

# Two gates for a prompt change: offline evals in CI, then a canary on live traffic.
BASELINE = {"format_valid": 1.00, "safety_cases": 1.00, "faithfulness": 0.91, "answer_relevance": 0.88}
HARD = {"format_valid", "safety_cases"}        # must be perfect
TOLERANCE = 0.02                                # judge-scored metrics may dip this much


def eval_gate(candidate):
    reasons = []
    for metric, base in BASELINE.items():
        got = candidate[metric]
        if metric in HARD and got < 1.0:
            reasons.append(f"{metric} {got:.2f} must be 1.00")
        elif metric not in HARD and got < base - TOLERANCE:
            reasons.append(f"{metric} {got:.2f} < baseline {base:.2f} - {TOLERANCE}")
    return ("PASS", []) if not reasons else ("BLOCK", reasons)


def canary(control, new, min_samples=500):
    if new["n"] < min_samples:
        return f"HOLD at 5%: only {new['n']} canary samples, need {min_samples}"
    if new["thumbs_down"] > control["thumbs_down"] * 1.2:
        return f"ROLL BACK: thumbs-down {new['thumbs_down']:.1%} vs {control['thumbs_down']:.1%}"
    if new["cost"] > control["cost"] * 1.25:
        return f"ROLL BACK: cost per task ${new['cost']:.4f} vs ${control['cost']:.4f}"
    if new["p95"] > control["p95"] * 1.2:
        return f"ROLL BACK: p95 {new['p95']}s vs {control['p95']}s"
    return "PROMOTE to 25%"


